-- Idempotent seed: NOT EXISTS avoids duplicate rows when entity_id IS NULL
-- (UNIQUE(name, entity_id) does not treat NULL entity_id as equal in PostgreSQL).

INSERT INTO roles (name, display_name, level, entity_type, is_system, permissions)
SELECT v.name, v.display_name, v.level, v.entity_type, v.is_system, v.permissions::jsonb
FROM (VALUES
  ('support',       'Support (ThinkSys)',  1000, 'system',   true, '{"actions":["visitor:create","visitor:read","visitor:update","visitor:delete","visit_request:create","visit_request:read","visit_request:approve","visit_request:reject","visit_request:checkin","visit_request:checkout","visit_request:more_info","qr:scan","qr:generate","qr:revoke","user:create","user:read","user:update","user:delete","user:impersonate","role:create","role:read","role:update","role:delete","role:assign","report:view","report:export","settings:read","settings:update","entity:create","entity:read","entity:update","entity:delete","audit_log:read","audit_log:export","watchlist:create","watchlist:read","watchlist:update","watchlist:delete","notification:configure","notification:send"],"not_actions":[]}'),
