  ('company',       'Company',             600,  'company',  true, '{"actions":["entity:read","entity:update","user:create","user:read","user:update","user:delete","role:create","role:read","role:assign","report:view","report:export","settings:read","settings:update","visitor:read","visit_request:read","audit_log:read","notification:configure","image:upload_self","image:upload_child","employee:csv_upload_self","employee:csv_upload_child"],"not_actions":[]}'),
  ('location',      'Location',            600,  'location', true, '{"actions":["entity:read","entity:update","user:create","user:read","user:update","user:delete","role:create","role:read","role:assign","report:view","report:export","settings:read","settings:update","visitor:read","visit_request:read","audit_log:read","notification:configure","image:upload_self","image:upload_child","employee:csv_upload_self","employee:csv_upload_child"],"not_actions":[]}'),
  ('admin',         'Admin',               400,  'any',      true, '{"actions":["user:create","user:read","user:update","role:create","role:read","role:assign","report:view","report:export","settings:read","settings:update","visitor:read","visit_request:read","visit_request:approve","visit_request:reject","visit_request:more_info","audit_log:read","notification:configure"],"not_actions":[]}'),
