  ('gate',          'Gate Receptionist',   100,  'any',      true, '{"actions":["visitor:create","visitor:read","visit_request:create","visit_request:read","visit_request:checkin","visit_request:checkout","qr:scan","qr:generate"],"not_actions":[]}')
) AS v(name, display_name, level, entity_type, is_system, permissions)
